  dialog: HTMLDialogElement,
  politeness: AnnouncePoliteness,
): void {
  clearModalRegion(dialog, politeness);
  dropHeld(dialog, politeness);
}

/**
 * Take the unexposed words out of a dialog's region, with their receipts,
 * clearing it.
